-- Каждая доставка всех четырёх типов отражена в ledger с теми же бизнес-полями, точным документом и payload. Batch ID доставки не сравнивается с исходным GP ID.
SELECT count(*) AS n FROM {{target:oil_stg__v_event_parsed}} p LEFT JOIN {{target:oil_dds__event}} e ON e.event_id=p.event_id WHERE e.event_id IS NULL OR e.event_type IS DISTINCT FROM p.event_type OR e.entity_id IS DISTINCT FROM p.entity_id OR e.entity_version IS DISTINCT FROM p.entity_version OR e.op IS DISTINCT FROM p.op OR e.event_time IS DISTINCT FROM p.event_time OR e.record_source IS DISTINCT FROM p.topic OR e.payload IS DISTINCT FROM p.payload OR e.event_document IS DISTINCT FROM p.event_json;
